        "hooks": [
          {
            "type": "command",
            "command": "python3 ~/.claude/hooks/hook-meter.py ~/.claude/hooks/hedge-scan.py"
          }
        ]
      },
      {
        "hooks": [
          {
            "type": "command",
            "command": "python3 ~/.claude/hooks/hook-meter.py ~/.claude/hooks/code-anchor-scan.py"
          }
        ]
      }
    ]
  },
  "statusLine": {
    "type": "command",
    "command": "bash ~/.claude/statusline-command.sh"
  },
